test("幅 200 の要素に幅 120 を当てると、当てた幅と今の高さで測れる", () => {
  const element = drawnWithStyle("width: 200px; height: 100px");

  expect(
    CanvasDom.layoutSizeFor(element, [AxisLength.create("width", 120)]),
  ).toEqual(Option.some({ width: 120, height: 100 }));
});

test("両軸に当てても、測り終えると style 属性が測る前と同じ文字列に戻る", () => {
  const before = "height:100px;width :200px; transform: rotate(30deg)";
  const element = drawnWithStyle(before);

  CanvasDom.layoutSizeFor(element, [
    AxisLength.create("width", 120),
    AxisLength.create("height", 80),
  ]);

  expect(element.getAttribute("style")).toBe(before);
});

test("style 属性の無い要素に長さを当てて測っても、測り終えると style 属性が無いまま", () => {
  const element = globalThis.document.createElement("div");
  globalThis.document.body.append(element);

  CanvasDom.layoutSizeFor(element, [AxisLength.create("width", 120)]);

  expect(element.hasAttribute("style")).toBe(false);
});

test("インライン指定の無い高さは、当てて測ったあとも指定が無いまま戻る", () => {
  const element = drawnWithStyle("width: 200px");

  const measured = CanvasDom.layoutSizeFor(element, [
    AxisLength.create("width", 120),
    AxisLength.create("height", 80),
  ]);

  // 当てた高さで測れたうえで（測れていなければ戻すところまで届いたかが分からない）、指定は残らない
  expect([measured, element.style.height]).toEqual([
    Option.some({ width: 120, height: 80 }),
    "",
  ]);
});

test("HTML の要素でない SVG は測れない", () => {
  const svg = globalThis.document.createElementNS(
    "http://www.w3.org/2000/svg",
    "svg",
  );
  svg.setAttribute("style", "width: 200px; height: 100px");
  globalThis.document.body.append(svg);

  expect(
    CanvasDom.layoutSizeFor(svg, [AxisLength.create("width", 120)]),
  ).toEqual(Option.none);
});

test("高さが px で読めない（fit-content の）要素は測れない", () => {
  const element = drawnWithStyle("width: 200px; height: fit-content");

  expect(
    CanvasDom.layoutSizeFor(element, [AxisLength.create("width", 120)]),
  ).toEqual(Option.none);
});

test("名前で指して長さを当てると、当てた幅と今の高さで測れる", () => {
  drawNamed("home", { left: 0, top: 0, width: 200, height: 100 }).setAttribute(
    "style",
    "width: 200px; height: 100px",
  );

  expect(
    DrawnBounds.measureLayoutSizeFor("home", [AxisLength.create("width", 120)]),
  ).toEqual(Option.some({ width: 120, height: 100 }));
});

test("描かれていない名前は、長さを当てても測れない", () => {
  drawNamed("home", { left: 0, top: 0, width: 200, height: 100 }).setAttribute(
    "style",
    "width: 200px; height: 100px",
  );

  expect(
    DrawnBounds.measureLayoutSizeFor("about", [
      AxisLength.create("width", 120),
    ]),
  ).toEqual(Option.none);
});

test("幅だけを掴んだとき、連れて変わりうるのは高さ", () => {
  expect(ResizeGrip.ungrabbedAxis(RightEdgeGrip)).toEqual(
    Option.some("height"),
  );
});

test("高さだけを掴んだとき、連れて変わりうるのは幅", () => {
  expect(
    ResizeGrip.ungrabbedAxis({
      kind: "height",
      height: { length: AxisLength.create("height", 100), end: "end" },
    }),
  ).toEqual(Option.some("width"));
});

test("角で 2 軸を掴んだとき、連れて変わる軸は無い", () => {
  expect(
    ResizeGrip.ungrabbedAxis({
      kind: "both",
      width: { length: AxisLength.create("width", 200), end: "end" },
      height: { length: AxisLength.create("height", 100), end: "end" },
    }),
  ).toEqual(Option.none);
});

test("90 度回したノードの右辺を引いて高さが連れて縮んでも、回る前の左上の角が親の座標で動かない", () => {
  const layoutSizeFor = followingLength("width", 80);
  const edit = turnedEditAt(
    {
      rotation: { own: 90, total: 90 },
      anchor: { x: 1, y: 0.5 },
      unrotatedMove: { x: 50, y: 0 },
    },
    layoutSizeFor,
  );

  const moved = cornerMoved(edit, {
    own: 90,
    anchor: { x: 0, y: 0 },
    layoutSizeFor,
  });
  expect(moved.x).toBeCloseTo(0);
  expect(moved.y).toBeCloseTo(0);
});

test("30 度回したノードの左辺を引いて高さが連れて伸びても、回る前の右上の角が親の座標で動かない", () => {
  const layoutSizeFor = followingLength("width", 130);
  const edit = turnedEditAt(
    {
      rotation: { own: 30, total: 30 },
      anchor: { x: 0, y: 0.5 },
      unrotatedMove: { x: 40, y: 0 },
    },
    layoutSizeFor,
  );

  const moved = cornerMoved(edit, {
    own: 30,
    anchor: { x: 1, y: 0 },
    layoutSizeFor,
  });
  expect(moved.x).toBeCloseTo(0);
  expect(moved.y).toBeCloseTo(0);
});

test("30 度回したノードの下辺を引いて幅が連れて変わっても、回る前の左上の角が親の座標で動かない", () => {
  const layoutSizeFor = followingLength("height", 170);
  const edit = turnedEditAt(
    {
      rotation: { own: 30, total: 30 },
      anchor: { x: 0.5, y: 1 },
      unrotatedMove: { x: 0, y: 40 },
    },
    layoutSizeFor,
  );

  const moved = cornerMoved(edit, {
    own: 30,
    anchor: { x: 0, y: 0 },
    layoutSizeFor,
  });
  expect(moved.x).toBeCloseTo(0);
  expect(moved.y).toBeCloseTo(0);
});

test("30 度回したノードの上辺を引いて幅が連れて変わっても、回る前の左下の角が親の座標で動かない", () => {
  const layoutSizeFor = followingLength("height", 230);
  const edit = turnedEditAt(
    {
      rotation: { own: 30, total: 30 },
      anchor: { x: 0.5, y: 0 },
      unrotatedMove: { x: 0, y: 30 },
    },
    layoutSizeFor,
  );

  const moved = cornerMoved(edit, {
    own: 30,
    anchor: { x: 0, y: 1 },
    layoutSizeFor,
  });
  expect(moved.x).toBeCloseTo(0);
  expect(moved.y).toBeCloseTo(0);
});

test("360 度回したノードは、高さが連れて変わっても回っていないものと同じ編集になる", () => {
  const gestureOf = (rotation: ResizeRotation) => ({
    rotation,
    anchor: { x: 1, y: 0.5 } as const,
    unrotatedMove: { x: 50, y: 0 },
  });

  expect(
    turnedEditAt(
      gestureOf({ own: 360, total: 360 }),
      followingLength("width", 80),
    ),
  ).toEqual(
    turnedEditAt(gestureOf({ own: 0, total: 0 }), followingLength("width", 80)),
  );
});

test("祖先だけが回っているノードは、高さが連れて変わっても右辺を引いて位置を書き換えない", () => {
  const edit = turnedEditAt(
    {
      rotation: { own: 0, total: 30 },
      anchor: { x: 1, y: 0.5 },
      unrotatedMove: { x: 50, y: 0 },
    },
    followingLength("width", 80),
  );

  expect(edit.position).toEqual(Option.none);
});

test("角を掴んだときは、測る大きさが前後で違っても、測れないときと同じ編集になる", () => {
  const resize = grabbedAt(
    placedTurned({ own: 30, total: 30 }),
    { x: 1, y: 1 },
    Offset.Origin,
  );
  const pointer = Offset.rotate({ x: 20, y: 20 }, 30);

  expect(
    resizeEditMeasuredAt(resize, pointer, followingLength("width", 80)),
  ).toEqual(Option.unwrap(resizeEditAt(resize, pointer, setupView())));
});

/*
 * 掴んだ軸だけで置き直すと、中心が回る前の右へ 25（親の座標で下へ 25）動き、左上はそこから
 * 25 戻るので (30 - 25, 70 + 25)。前後とも測れて高さが 100 → 30 なら (40, 130) になる。
 */

test("掴んだ時点も今も大きさを測れないときは、掴んだ軸だけで置き直す", () => {
  const position = rightEdgePulledPosition(() => Option.none);

  expect(position.x).toBeCloseTo(5);
  expect(position.y).toBeCloseTo(95);
});

test("掴んだ時点の大きさだけを測れないときは、掴んだ軸だけで置き直す", () => {
  const position = rightEdgePulledPosition(measuredOnlyOneSide("grabbed"));

  expect(position.x).toBeCloseTo(5);
  expect(position.y).toBeCloseTo(95);
});

test("今の大きさだけを測れないときは、掴んだ軸だけで置き直す", () => {
  const position = rightEdgePulledPosition(measuredOnlyOneSide("current"));

  expect(position.x).toBeCloseTo(5);
  expect(position.y).toBeCloseTo(95);
});

test("回したフロー配置のノードは、高さが連れて変わっても位置を書かない", () => {
  const resize = grabbedAt(
    { ...setupFlowResizable(), rotation: { own: 30, total: 30 } },
    { x: 1, y: 0.5 },
    Offset.Origin,
  );

  const edit = resizeEditMeasuredAt(
    resize,
    Offset.rotate({ x: 50, y: 0 }, 30),
    followingLength("width", 80),
  );

  expect(edit.position).toEqual(Option.none);
});

test("90 度回したノードの右辺を 50 引いて高さが連れて 80 に縮むと、回る前の左上の角が留まる位置が通知される", () => {
  /*
   * 掴んだ幅だけなら (25 - 25, 10 + 25)。高さが 100 → 80 で回る前の上端を留めると、中心は
   * 回る前の上へ 10（画面では右へ 10）動き、左上は中心から 10 戻るので (0 + 10, 35 + 10)。
   */
  const onResize = vi.fn();
  renderCanvas({ selection: setupWrappingTurned(), onResize });
  const turned = drawnTurned("turned");

  pressPointer(resizeHandleAt({ x: 1, y: 0.5 }), { x: 150, y: 200 });
  movePointer(turned, { x: 150, y: 250 });

  const position = Option.unwrap(lastEdit(onResize).position);
  expect(position.x).toBeCloseTo(10);
  expect(position.y).toBeCloseTo(45);
});

test("高さが連れて変わっても、通知は動かした回数だけで、離したときに追加の通知は出ない", () => {
  const onResize = vi.fn();
  renderCanvas({ selection: setupWrappingTurned(), onResize });
  const turned = drawnTurned("turned");

  pressPointer(resizeHandleAt({ x: 1, y: 0.5 }), { x: 150, y: 200 });
  movePointer(turned, { x: 150, y: 225 });
  movePointer(turned, { x: 150, y: 250 });
  releasePointer(turned, { x: 150, y: 250 });

  expect(onResize).toHaveBeenCalledTimes(2);
});

function dragWrappingRightEdge(): void {
  stubHeightFollowingWidth("turned");
  const turned = drawnTurnedAt(
    "turned",
    { left: 100, top: 0, width: 100, height: 200 },
    { width: 200, height: 100 },
  );
  pressPointer(turned, { x: 150, y: 195 });
  movePointer(canvasContent(), { x: 150, y: 220 });
  movePointer(canvasContent(), { x: 150, y: 245 });
  releasePointer(canvasContent(), { x: 150, y: 245 });
}

test("高さが幅につれて変わる回ったノードの右辺を 2 回に分けて運んで離すと、回る前の左上の角が留まる位置で描かれる", async () => {
  await renderOpenedDocument(setupDocument());
  await selectInTree("turned");

  dragWrappingRightEdge();

  const turned = drawn("turned");
  expect([turned.style.width, turned.style.left, turned.style.top]).toEqual([
    "250px",
    "10px",
    "45px",
  ]);
});

test("高さが幅につれて変わる回ったノードを運んだあと 1 回戻すと、幅も位置も掴む前に戻る", async () => {
  await renderOpenedDocument(setupDocument());
  await selectInTree("turned");
  dragWrappingRightEdge();

  await userEvent.keyboard("{Control>}z{/Control}");

  const turned = drawn("turned");
  expect([turned.style.width, turned.style.left, turned.style.top]).toEqual([
    "200px",
    "25px",
    "10px",
  ]);
});

layoutSizeFor(
  element: Element,
  lengths: readonly AxisLength[],
): Option<Readonly<{ width: number; height: number }>> {
  if (!(element instanceof HTMLElement)) {
    return Option.none;
  }

  const inlineStyle = Option.fromNullable(element.getAttribute("style"));
  for (const each of lengths) {
    element.style.setProperty(each.axis, Px.create(each.length));
  }

  const computed = globalThis.getComputedStyle(element);
  const width = pxLengthOf(computed.width);
  const height = pxLengthOf(computed.height);

  if (Option.isSome(inlineStyle)) {
    element.setAttribute("style", inlineStyle.value);
  } else {
    element.removeAttribute("style");
  }

  return Option.flatMap(width, (measuredWidth) =>
    Option.map(height, (measuredHeight) => ({
      width: measuredWidth,
      height: measuredHeight,
    })),
  );
},

function ungrabbedEnd(
  held: ResizeHold,
  lengths: AxisLengths,
  layoutSizeFor: DrawnWhileTracking["layoutSizeFor"],
): Option<ShrunkEnd> {
  // 回っていなければ終点側の端が動いても左上は動かない。測ると強制レイアウトが無駄になるので先に外す
  if (Angle.isWholeTurns(held.rotation.own)) {
    return Option.none;
  }
  // 位置を書けなければ置き直さないので、同じく測る前に外す
  if (!Option.isSome(held.grabbedAt)) {
    return Option.none;
  }
  const axis = ResizeGrip.ungrabbedAxis(held.grip);
  if (!Option.isSome(axis)) {
    return Option.none;
  }

  const grabbedLengths = ArrayEx.mapNonEmpty(
    ResizeGrip.grabs(held.grip),
    (grab) => grab.length,
  );

  return Option.flatMap(layoutSizeFor(grabbedLengths), (before) =>
    Option.map(layoutSizeFor(lengths), (after) => ({
      axis: axis.value,
      end: AxisEnds.End,
      shrunk: before[axis.value] - after[axis.value],
    })),
  );
}

export function stubComputedSizeOf(
  name: string,
  sizeFor: ComputedSizeFor,
): void {
  computedSizeByName.set(name, sizeFor);
  if (originalGetComputedStyle !== undefined) {
    return;
  }
  const original = globalThis.getComputedStyle;
  originalGetComputedStyle = original;
  globalThis.getComputedStyle = (element, pseudoElement) => {
    const computed = original(element, pseudoElement);
    const stubbed = computedSizeByName.get(
      element.getAttribute(ElementNameAttribute) ?? "",
    );
    if (stubbed === undefined) {
      return computed;
    }
    if (!(element instanceof HTMLElement)) {
      return computed;
    }
    if (!element.isConnected) {
      return computed;
    }
    const size = stubbed(element.style);
    Object.defineProperty(computed, "width", {
      configurable: true,
      value: `${size.width}px`,
    });
    Object.defineProperty(computed, "height", {
      configurable: true,
      value: `${size.height}px`,
    });
    return computed;
  };
}
